with open(PATH, "r", encoding="utf-8") as f:
    content = f.read()

marker = "export const products: Product[] = "
start = content.find(marker)
if start == -1:
    raise SystemExit("No se encontro el marcador esperado en products.ts")
arr_start = start + len(marker)
end = content.rfind("];")
if end == -1:
    raise SystemExit("No se encontro el cierre del array en products.ts")

header = content[:arr_start]
tail = content[end + 2:]
products = json.loads(content[arr_start:end + 1])

by_code = {}
for a in ADDITIONS:
    by_code.setdefault(a["code"], []).append(a)

added = 0
skipped_existing = 0
skipped_no_product = 0
codes_seen = set(p["code"] for p in products)

for code, items in by_code.items():
    if code not in codes_seen:
        skipped_no_product += len(items)
        print(f"AVISO: referencia {code} no existe en products.ts, se omite")
        continue

for p in products:
    items = by_code.get(p["code"])
    if not items:
        continue
    existing_names = set(c["name"] for c in p["colors"])
    for item in items:
        if item["name"] in existing_names:
            skipped_existing += 1
            continue
        p["colors"].append({"name": item["name"], "hex": item["hex"], "image": item["image"]})
        existing_names.add(item["name"])
        added += 1

arr_json = json.dumps(products, ensure_ascii=False, separators=(",", ": "))
new_content = header + arr_json + ";" + tail

with open(PATH, "w", encoding="utf-8") as f:
    f.write(new_content)

print(f"Colores añadidos: {added}")
print(f"Ya existian (omitidos): {skipped_existing}")
print(f"Referencias no encontradas: {skipped_no_product}")
